"""CSV decoding and validation, independent of report dates."""
import csv
import io
from datetime import datetime, timezone

from .model import Shift

FIELDS = ["employee", "start", "end", "status"]


def parse_instant(text: str) -> datetime:
    instant = datetime.fromisoformat(text.strip())
    if instant.tzinfo is None or instant.utcoffset() is None:
        raise ValueError("shift timestamps require a UTC offset")
    return instant.astimezone(timezone.utc)


def read_shifts(text: str) -> list[Shift]:
    reader = csv.DictReader(io.StringIO(text))
    if reader.fieldnames != FIELDS:
        raise ValueError("unexpected CSV fields")
    shifts = []
    for row in reader:
        if None in row or any(value is None for value in row.values()):
            raise ValueError("incomplete CSV row")
        employee, status = row["employee"].strip(), row["status"].strip()
        if not employee or status not in {"confirmed", "void"}:
            raise ValueError("invalid employee or status")
        start, end = parse_instant(row["start"]), parse_instant(row["end"])
        if end <= start:
            raise ValueError("shift end must be later than start")
        shifts.append(Shift(employee, start, end, status))
    return shifts

"""Validated domain records; instants are normalized at import."""
from dataclasses import dataclass
from datetime import datetime


@dataclass(frozen=True)
class Shift:
    employee: str
    start: datetime
    end: datetime
    status: str

    @property
    def duration_minutes(self) -> float:
        return (self.end - self.start).total_seconds() / 60.0

"""Aggregate confirmed staffing time for a daily report."""
from collections.abc import Iterable

from ..model import Shift
from ..windows import DayWindow


def report_minutes(shifts: Iterable[Shift], window: DayWindow) -> dict[str, float]:
    totals: dict[str, float] = {}
    for shift in shifts:
        if shift.status != "confirmed":
            continue
        minutes = window.overlap_minutes(shift)
        if minutes <= 0.0:
            continue
        totals[shift.employee] = totals.get(shift.employee, 0.0) + minutes
    return dict(sorted(totals.items()))

"""Calendar-day windows at explicit fixed UTC offsets."""
from dataclasses import dataclass
from datetime import date, datetime, timedelta, timezone
import re

from .model import Shift


def fixed_offset(text: str) -> timezone:
    if re.fullmatch(r"[+-](?:0\d|1\d|2[0-3]):[0-5]\d", text) is None:
        raise ValueError("invalid fixed UTC offset")
    sign = 1 if text[0] == "+" else -1
    return timezone(sign * timedelta(hours=int(text[1:3]), minutes=int(text[4:])))


@dataclass(frozen=True)
class DayWindow:
    start: datetime
    end: datetime

    def overlap_minutes(self, shift: Shift) -> float:
        """Minutes of the shift that fall within this window."""
        start = max(shift.start, self.start)
        end = min(shift.end, self.end)
        if start >= end:
            return 0.0
        return (end - start).total_seconds() / 60.0


def day_window(day: str, offset: str) -> DayWindow:
    local_date = date.fromisoformat(day)
    start = datetime.combine(local_date, datetime.min.time(), fixed_offset(offset))
    return DayWindow(start, start + timedelta(days=1))
